// A tiny todo list with due dates, priorities and JSON persistence.
import { readFileSync, writeFileSync } from "node:fs";

export const PRIORITIES = ["low", "normal", "high"];

function parseDue(due) {
  if (due === undefined || due === null) return null;
  const d = due instanceof Date ? due : new Date(due);
  if (Number.isNaN(d.getTime())) throw new Error("invalid due date");
  return d.toISOString();
}

export class TodoList {
  constructor() { this.items = []; this.nextId = 1; }

  add(title, { due, priority = "normal" } = {}) {
    if (!title) throw new Error("title is required");
    if (!PRIORITIES.includes(priority)) throw new Error(`invalid priority: ${priority}`);
    const item = { id: this.nextId++, title, done: false, due: parseDue(due), priority };
    this.items.push(item);
    return item;
  }

  complete(id) {
    const item = this.items.find(i => i.id === id);
    if (!item) throw new Error(`item ${id} not found`);
    item.done = true;
    return item;
  }

  pending() {
    return this.items.filter(i => !i.done);
  }

  clear() {
    this.items = this.items.filter(i => !i.done);
  }

  addTag(id, tag) {
    const item = this.items.find(i => i.id === id);
    if (!item) throw new Error(`item ${id} not found`);
    const t = typeof tag === "string" ? tag.trim().toLowerCase() : "";
    if (!t) throw new Error("tag is required");
    if (!item.tags) item.tags = [];
    if (!item.tags.includes(t)) item.tags.push(t);
    return item;
  }

  removeTag(id, tag) {
    const item = this.items.find(i => i.id === id);
    if (!item) throw new Error(`item ${id} not found`);
    const t = typeof tag === "string" ? tag.trim().toLowerCase() : "";
    item.tags = (item.tags ?? []).filter(x => x !== t);
    return item;
  }

  byTag(tag) {
    const t = typeof tag === "string" ? tag.trim().toLowerCase() : "";
    return this.items.filter(i => (i.tags ?? []).includes(t));
  }

  // Case-insensitive; every whitespace-separated term must match the title or a tag.
  search(query) {
    const terms = String(query ?? "").toLowerCase().split(/\s+/).filter(Boolean);
    if (terms.length === 0) return [];
    return this.items.filter(i => {
      const text = [i.title, ...(i.tags ?? [])].join(" ").toLowerCase();
      return terms.every(w => text.includes(w));
    });
  }

  // Overdue first, then priority (high to low), then due date (none last), then id.
  sorted(now = new Date()) {
    const t = new Date(now).getTime();
    const overdue = i => !i.done && i.due !== null && new Date(i.due).getTime() < t;
    const dueTime = i => (i.due === null ? Infinity : new Date(i.due).getTime());
    return [...this.items].sort((a, b) =>
      overdue(b) - overdue(a) ||
      PRIORITIES.indexOf(b.priority) - PRIORITIES.indexOf(a.priority) ||
      (dueTime(a) === dueTime(b) ? 0 : dueTime(a) < dueTime(b) ? -1 : 1) ||
      a.id - b.id);
  }

  save(path) {
    writeFileSync(path, JSON.stringify({ nextId: this.nextId, items: this.items }, null, 2));
  }

  static load(path) {
    const data = JSON.parse(readFileSync(path, "utf8"));
    const list = new TodoList();
    list.items = data.items.map(i => ({
      done: false, due: null, priority: "normal", ...i,
    }));
    list.nextId = Math.max(data.nextId ?? 1, ...list.items.map(i => i.id + 1));
    return list;
  }
}

// --- Recurring todos (added as separate functions; existing API untouched) ---
export const RECURRENCES = ["daily", "weekly", "monthly"];

// Next due date (ISO string) after `due` for a recurrence. Monthly dates are
// clamped to the month's last day; `day` is the anchor day-of-month so that
// Jan 31 -> Feb 28 -> Mar 31 rather than drifting to the 28th.
export function nextDue(due, repeat, day) {
  if (!RECURRENCES.includes(repeat)) throw new Error(`invalid recurrence: ${repeat}`);
  const d = new Date(due);
  if (Number.isNaN(d.getTime())) throw new Error("invalid due date");
  if (repeat === "daily") d.setUTCDate(d.getUTCDate() + 1);
  else if (repeat === "weekly") d.setUTCDate(d.getUTCDate() + 7);
  else {
    const anchor = day ?? d.getUTCDate();
    d.setUTCDate(1);
    d.setUTCMonth(d.getUTCMonth() + 1);
    const last = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate();
    d.setUTCDate(Math.min(anchor, last));
  }
  return d.toISOString();
}

// Add a recurring todo. `repeat` is one of RECURRENCES; `due` defaults to now.
TodoList.prototype.addRecurring = function (title, repeat, { due = new Date(), priority } = {}) {
  if (!RECURRENCES.includes(repeat)) throw new Error(`invalid recurrence: ${repeat}`);
  const item = this.add(title, { due, priority });
  item.repeat = repeat;
  item.repeatDay = new Date(item.due).getUTCDate();
  return item;
};

// Complete an item; if it recurs, schedule the next occurrence.
// Returns { item, next } where next is null for non-recurring items.
TodoList.prototype.completeAndReschedule = function (id) {
  const found = this.items.find(i => i.id === id);
  if (!found) throw new Error(`item ${id} not found`);
  const wasDone = found.done;
  const item = this.complete(id);
  if (wasDone || !item.repeat) return { item, next: null };
  const next = this.add(item.title, { due: nextDue(item.due, item.repeat, item.repeatDay), priority: item.priority });
  next.repeat = item.repeat;
  next.repeatDay = item.repeatDay;
  return { item, next };
};

