#!/usr/bin/env node
// Usage: todo add <title> [--due DATE] [--priority low|normal|high]
//        todo done <id>
//        todo list [--tag TAG]
//        todo search <query>
//        todo tag <id> <tag> | untag <id> <tag>
//        todo recur <id> <daily|weekly|monthly|none>
//        todo export --json | --csv
// The list is stored in $TODO_FILE (default: ./todo.json).
import { existsSync } from "node:fs";
import { TodoList } from "../src/todo.js";

const file = process.env.TODO_FILE ?? "todo.json";
const [cmd, ...args] = process.argv.slice(2);

function fail(msg) {
  console.error(msg);
  process.exit(1);
}

function printItems(items) {
  for (const i of items) {
    const due = i.due ? ` (due ${i.due.slice(0, 10)})` : "";
    const tags = i.tags?.length ? ` #${i.tags.join(" #")}` : "";
    const repeat = i.repeat ? ` (${i.repeat})` : "";
    console.log(`${i.id} [${i.done ? "x" : " "}] ${i.priority} ${i.title}${due}${repeat}${tags}`);
  }
}

function csvField(v) {
  const s = v === null || v === undefined ? "" : Array.isArray(v) ? v.join(";")
    : typeof v === "object" ? JSON.stringify(v) : String(v);
  return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

function toCsv(items) {
  const cols = ["id", "title", "done", "due", "priority", "tags", "repeat"];
  return [cols.join(","), ...items.map(i => cols.map(c => csvField(i[c])).join(","))].join("\n");
}

const list = existsSync(file) ? TodoList.load(file) : new TodoList();

try {
  if (cmd === "add") {
    const opts = {};
    const words = [];
    for (let i = 0; i < args.length; i++) {
      if (args[i] === "--due") opts.due = args[++i];
      else if (args[i] === "--priority") opts.priority = args[++i];
      else words.push(args[i]);
    }
    const item = list.add(words.join(" "), opts);
    list.save(file);
    console.log(`added ${item.id}: ${item.title}`);
  } else if (cmd === "done") {
    const { item, next } = list.completeAndReschedule(Number(args[0]));
    list.save(file);
    console.log(`completed ${item.id}: ${item.title}`);
    if (next) console.log(`next ${next.id}: due ${next.due.slice(0, 10)}`);
  } else if (cmd === "list") {
    let items = list.sorted();
    const t = args.indexOf("--tag");
    if (t !== -1) {
      if (!args[t + 1]) fail("--tag requires a value");
      const tagged = new Set(list.byTag(args[t + 1]));
      items = items.filter(i => tagged.has(i));
    }
    printItems(items);
  } else if (cmd === "search") {
    if (!args.length) fail("search requires a query");
    printItems(list.search(args.join(" ")));
  } else if (cmd === "tag" || cmd === "untag") {
    if (!args[1]) fail(`usage: todo ${cmd} <id> <tag>`);
    const id = Number(args[0]);
    if (cmd === "tag") list.addTag(id, args[1]);
    else list.removeTag(id, args[1]);
    list.save(file);
    console.log(`${cmd === "tag" ? "tagged" : "untagged"} ${id}: ${args[1]}`);
  } else if (cmd === "recur") {
    const freq = args[1];
    if (!["daily", "weekly", "monthly", "none"].includes(freq)) {
      fail("usage: todo recur <id> <daily|weekly|monthly|none>");
    }
    const item = list.items.find(i => i.id === Number(args[0]));
    if (!item) fail(`item ${args[0]} not found`);
    if (freq === "none") {
      delete item.repeat;
      delete item.repeatDay;
    } else {
      if (!item.due) fail(`item ${item.id} needs a due date to recur`);
      item.repeat = freq;
      item.repeatDay = new Date(item.due).getUTCDate();
    }
    list.save(file);
    console.log(`recurrence for ${args[0]}: ${freq}`);
  } else if (cmd === "export") {
    if (args.includes("--json")) console.log(JSON.stringify(list.items, null, 2));
    else if (args.includes("--csv")) console.log(toCsv(list.items));
    else fail("usage: todo export --json | --csv");
  } else {
    fail("usage: todo add <title> [--due DATE] [--priority P] | done <id> | list [--tag T] | search <q> | tag | untag | recur | export");
  }
} catch (e) {
  fail(e.message);
}

