// A tiny todo list with due dates, priorities and JSON persistence.
import { readFileSync, writeFileSync } from "node:fs";

export const PRIORITIES = ["low", "normal", "high"];

function parseDue(due) {
  if (due === undefined || due === null) return null;
  const d = due instanceof Date ? due : new Date(due);
  if (Number.isNaN(d.getTime())) throw new Error("invalid due date");
  return d.toISOString();
}

export class TodoList {
  constructor() { this.items = []; this.nextId = 1; }

  add(title, { due, priority = "normal" } = {}) {
    if (typeof title !== "string" || !title.trim()) throw new Error("title is required");
    if (!PRIORITIES.includes(priority)) throw new Error(`invalid priority: ${priority}`);
    const item = { id: this.nextId++, title: title.trim(), done: false, due: parseDue(due), priority };
    this.items.push(item);
    return item;
  }

  complete(id) {
    const item = this.items.find(i => i.id === id);
    if (!item) throw new Error(`item ${id} not found`);
    item.done = true;
    return item;
  }

  pending() {
    return this.items.filter(i => !i.done);
  }

  clear() {
    this.items = this.items.filter(i => !i.done);
  }

  addTag(id, tag) {
    const item = this.items.find(i => i.id === id);
    if (!item) throw new Error(`item ${id} not found`);
    const t = typeof tag === "string" ? tag.trim().toLowerCase() : "";
    if (!t) throw new Error("tag is required");
    if (!item.tags) item.tags = [];
    if (!item.tags.includes(t)) item.tags.push(t);
    return item;
  }

  removeTag(id, tag) {
    const item = this.items.find(i => i.id === id);
    if (!item) throw new Error(`item ${id} not found`);
    const t = typeof tag === "string" ? tag.trim().toLowerCase() : "";
    if (item.tags) item.tags = item.tags.filter(x => x !== t);
    return item;
  }

  byTag(tag) {
    const t = typeof tag === "string" ? tag.trim().toLowerCase() : "";
    return this.items.filter(i => (i.tags ?? []).includes(t));
  }

  // Case-insensitive; every whitespace-separated term must match the title or a tag.
  search(query) {
    const terms = String(query ?? "").toLowerCase().split(/\s+/).filter(Boolean);
    if (terms.length === 0) return [];
    return this.items.filter(i => {
      const text = [i.title, ...(i.tags ?? [])].join(" ").toLowerCase();
      return terms.every(w => text.includes(w));
    });
  }

  // Overdue first, then priority (high to low), then due date (none last), then id.
  sorted(now = new Date()) {
    const t = new Date(now).getTime();
    if (Number.isNaN(t)) throw new Error("invalid date");
    const overdue = i => !i.done && i.due !== null && new Date(i.due).getTime() < t;
    const dueTime = i => (i.due === null ? Infinity : new Date(i.due).getTime());
    return [...this.items].sort((a, b) =>
      overdue(b) - overdue(a) ||
      PRIORITIES.indexOf(b.priority) - PRIORITIES.indexOf(a.priority) ||
      (dueTime(a) === dueTime(b) ? 0 : dueTime(a) < dueTime(b) ? -1 : 1) ||
      a.id - b.id);
  }

  save(path) {
    writeFileSync(path, JSON.stringify({ nextId: this.nextId, items: this.items }, null, 2));
  }

  static load(path) {
    const data = JSON.parse(readFileSync(path, "utf8"));
    if (!data || typeof data !== "object" || !Array.isArray(data.items)) {
      throw new Error(`corrupt todo file: ${path}`);
    }
    const list = new TodoList();
    const seen = new Set();
    list.items = data.items.map(i => {
      if (!i || !Number.isInteger(i.id) || seen.has(i.id) || typeof i.title !== "string") {
        throw new Error(`corrupt todo file: bad item in ${path}`);
      }
      seen.add(i.id);
      const item = { done: false, due: null, priority: "normal", ...i };
      parseDue(item.due);
      if (!PRIORITIES.includes(item.priority)) throw new Error(`corrupt todo file: bad priority in ${path}`);
