#!/usr/bin/env node
// Usage: todo add <title> [--due DATE] [--priority low|normal|high]
//        todo done <id>
//        todo list [--tag TAG]
//        todo search <query>
//        todo tag <id> <tag> | untag <id> <tag>
//        todo recur <id> <daily|weekly|monthly|none>
//        todo export --json | --csv
// The list is stored in $TODO_FILE (default: ./todo.json).
import { existsSync } from "node:fs";
import { TodoList } from "../src/todo.js";

const file = process.env.TODO_FILE ?? "todo.json";
const [cmd, ...args] = process.argv.slice(2);

function fail(msg) {
  console.error(msg);
  process.exit(1);
}

function printItems(items) {
  for (const i of items) {
    const due = i.due ? ` (due ${i.due.slice(0, 10)})` : "";
    const tags = i.tags?.length ? ` #${i.tags.join(" #")}` : "";
    const repeat = i.repeat ? ` (${i.repeat})` : "";
    console.log(`${i.id} [${i.done ? "x" : " "}] ${i.priority} ${i.title}${due}${repeat}${tags}`);
  }
}

function csvField(v) {
  const s = v === null || v === undefined ? "" : Array.isArray(v) ? v.join(";")
    : typeof v === "object" ? JSON.stringify(v) : String(v);
  return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

function toCsv(items) {
  const cols = ["id", "title", "done", "due", "priority", "tags", "repeat"];
  return [cols.join(","), ...items.map(i => cols.map(c => csvField(i[c])).join(","))].join("\n");
}

function parseId(v) {
  if (!/^\d+$/.test(v ?? "")) fail(`invalid id: ${v ?? "(missing)"}`);
  return Number(v);
}

function optValue(name, v) {
  if (v === undefined || v.startsWith("--")) fail(`${name} requires a value`);
  return v;
}

try {
  const list = existsSync(file) ? TodoList.load(file) : new TodoList();
  if (cmd === "add") {
    const opts = {};
    const words = [];
    for (let i = 0; i < args.length; i++) {
      if (args[i] === "--due") opts.due = optValue("--due", args[++i]);
