import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawnSync } from "node:child_process";
import { TodoList } from "../src/todo.js";

function setup() {
  const dir = mkdtempSync(join(tmpdir(), "todo-edge-"));
  const file = join(dir, "t.json");
  const env = { ...process.env, TODO_FILE: file };
  const run = (...args) => spawnSync("node", ["bin/todo.js", ...args], { env, encoding: "utf8" });
  return { dir, file, run, cleanup: () => rmSync(dir, { recursive: true }) };
}

test("empty list: sorted, search, byTag, pending, clear", () => {
  const l = new TodoList();
  assert.deepEqual(l.sorted(), []);
  assert.deepEqual(l.search("x"), []);
  assert.deepEqual(l.byTag("x"), []);
  assert.deepEqual(l.pending(), []);
  l.clear();
  assert.deepEqual(l.items, []);
});

test("bad titles and dates are rejected", () => {
  const l = new TodoList();
  assert.throws(() => l.add("   "), /title/);
  assert.throws(() => l.add(5), /title/);
  assert.throws(() => l.add("x", { due: "not a date" }), /invalid due/);
  assert.throws(() => l.sorted("garbage"), /invalid date/);
  assert.equal(l.add("  padded  ").title, "padded");
});

test("unicode titles and tags round-trip and search", () => {
  const { file, cleanup } = setup();
  try {
    const l = new TodoList();
    l.add("café ☕ 日本語");
    l.addTag(1, "Ünï");
    l.save(file);
    const back = TodoList.load(file);
    assert.equal(back.search("日本")[0].title, "café ☕ 日本語");
    assert.equal(back.byTag("ünï").length, 1);
  } finally { cleanup(); }
});

test("removeTag on untagged item does not add a tags field", () => {
  const l = new TodoList();
  l.add("a");
  l.removeTag(1, "x");
  assert.equal("tags" in l.items[0], false);
});

test("recurring reschedule keeps tags", () => {
  const l = new TodoList();
  l.addRecurring("rent", "monthly", { due: "2026-01-31" });
  l.addTag(1, "home");
  const { next } = l.completeAndReschedule(1);
  assert.deepEqual(next.tags, ["home"]);
});

test("corrupt save files fail with a clean error", () => {
  const { file, run, cleanup } = setup();
  try {
    for (const body of ["", "{not json", "{}", "[]", "null",
      '{"items":[{"title":"no id"}]}',
      '{"items":[{"id":1,"title":"a"},{"id":1,"title":"b"}]}',
      '{"items":[{"id":1}]}',
      '{"items":[{"id":1,"title":"a","due":"garbage"}]}',
      '{"items":[{"id":1,"title":"a","priority":"urgent"}]}']) {
      writeFileSync(file, body);
      const r = run("list");
      assert.equal(r.status, 1, `body: ${body}`);
      assert.doesNotMatch(r.stderr, /\bat .*\(.*:\d+:\d+\)/, `stack trace for: ${body}`);
    }
  } finally { cleanup(); }
});

test("load tolerates missing nextId", () => {
  const { file, cleanup } = setup();
  try {
    writeFileSync(file, '{"items":[{"id":4,"title":"a"}]}');
    assert.equal(TodoList.load(file).add("b").id, 5);
  } finally { cleanup(); }
});

test("cli: missing option values and bad ids", () => {
  const { run, cleanup } = setup();
  try {
    assert.equal(run("add", "x", "--due").status, 1);
    assert.equal(run("add", "x", "--priority").status, 1);
    assert.equal(run("add", "x", "--due", "--priority", "high").status, 1);
    assert.equal(run("add", "   ").status, 1);
    run("add", "real");
    for (const id of ["0x1", "1e0", "+1", "1.5", "abc", ""]) {
      assert.equal(run("done", id).status, 1, `done ${id}`);
    }
    assert.equal(run("done").status, 1);
    assert.equal(run("recur", "1").status, 1);
    assert.equal(run("done", "1").status, 0);
    assert.equal(run("recur", "1", "daily").status, 1); // already done
  } finally { cleanup(); }
});

test("cli: empty list output and unicode CSV export", () => {
  const { run, cleanup } = setup();
  try {
    assert.equal(run("list").stdout, "");
    run("add", 'naïve "quoted", 日本語');
    const csv = run("export", "--csv").stdout;
    assert.match(csv, /"naïve ""quoted"", 日本語"/);
    assert.equal(JSON.parse(run("export", "--json").stdout)[0].title, 'naïve "quoted", 日本語');
  } finally { cleanup(); }
});

